 use serde :: { Deserialize , Serialize } ; use std :: collections :: HashMap ; fn extract_decl_type (file_path : & Path) -> Option < String > { let filename = file_path . file_stem () ? . to_str () ? ; if filename . contains ("_struct_") { Some ("struct" . to_string ()) } else if filename . contains ("_enum_") { Some ("enum" . to_string ()) } else if filename . contains ("_impl_") { Some ("impl" . to_string ()) } else if filename . contains ("_fn_") { Some ("function" . to_string ()) } else if filename . contains ("_const_") { Some ("const" . to_string ()) } else if filename . contains ("_trait_") { Some ("trait" . to_string ()) } else if filename . contains ("_type_") { Some ("type" . to_string ()) } else if filename . contains ("_static_") { Some ("static" . to_string ()) } else { Some ("other" . to_string ()) } }